addEventListener('keydown',e=>{if(modal.open||journal.open||$('#memory-prepare').open)return;if(keepsakeActive||$('#wish-card').open){if(e.key==='Escape')closeKeepsake();return;}if(memoryOpen){if(e.key==='ArrowLeft'){e.preventDefault();moveMemory(-1);}if(e.key==='ArrowRight'){e.preventDefault();moveMemory(1);}if(e.key==='Escape')closeMemories();return;}if(['ArrowRight','ArrowUp','w','d'].includes(e.key)){e.preventDefault();if(!arrival){arrival=true;updateUI();}else if(index<7)go(index+1);}if(['ArrowLeft','ArrowDown','a','s'].includes(e.key)&&index>0){e.preventDefault();go(index-1);}});

